mapper.select:

where ss.schedule_resource_id = #{scheduleResourceId}
  and ss.deleted = 0
order by ss.scope_id asc


where ss.schedule_resource_id = #{scheduleResourceId}
  and ss.allowed_schedule_id = #{allowedScheduleId}
  and ss.enabled = 1
  and ss.deleted = 0
order by ss.scope_id desc
limit 1

select count(1)
from competition_scene_resource_schedule_scope
where schedule_resource_id = #{scheduleResourceId}
  and allowed_schedule_id = #{allowedScheduleId}
  and enabled = 1
  and deleted = 0
